package gg.pixelkingdomwars.nativeclient.vehicle
import gg.pixelkingdomwars.nativeclient.charter.*
import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test
class VehicleProtocolTest {
 private val f=Json.parseToJsonElement(requireNotNull(javaClass.getResource("/vehicle-client-vectors.json")).readText()).jsonObject
 private val rows=f.getValue("vectors").jsonArray.map{it.jsonObject};private val policy=VehiclePolicy.from(f.charterObject("constants"));private val c=rows.first().charterObject("client")
 private fun change(o:JsonObject,path:String,value:JsonElement):JsonObject{val p=path.split('.',limit=2);return JsonObject(o+(p[0] to if(p.size==1)value else change(o.charterObject(p[0]),p[1],value)))}
 @Test fun `old arbitrary request keys are retained as one encoded path component`() {assertEquals("/vehicles/client/installations/by-key/old%20key%2F%25%3F%23%2B%E2%98%83",VehicleProtocol.byKeyPath("installation","old key/%?#+☃"))}
 @Test fun `all original public clients preserve exact consent and service effect JSON`() {for(r in rows){val client=r.charterObject("client");assertEquals(client,VehicleProtocol.client(client));policy.verifyClient(client);if(r.charterText("kind")!="installation")assertEquals(r.charterText("serviceJson"),policy.serviceEffect(VehicleProtocol.original(client).charterObject("state")).toString())}}
 @Test fun `false authority flags canonical timestamps and closed fields are mandatory`() {for((path,value) in listOf("record.signingAuthorized" to JsonPrimitive(true),"record.serverNow" to JsonPrimitive("2035-01-01T00:00:00.000001Z"),"record.reservation.reservedAt" to JsonPrimitive("2035-01-01T00:00:00.000Z"),"record.preparation.lastValidBlockHeight" to JsonPrimitive("123")))assertThrows(Exception::class.java){VehicleProtocol.client(change(c,path,value))};assertThrows(Exception::class.java){VehicleProtocol.client(JsonObject(c+("trust" to buildJsonObject{})))}}
 @Test fun `actor key source and preparation graph cannot contradict original reservation`() {for((path,value) in listOf("record.idempotencyKey" to JsonPrimitive("changed"),"record.wallet" to c.charterObject("consentSource").getValue("genesisHash"),"consentSource" to JsonNull,"record.status" to JsonPrimitive("installed")))assertThrows(Exception::class.java){VehicleProtocol.client(change(c,path,value))}}
 @Test fun `requests reject replacement cancellation actor overrides and malformed discovery cursors`() {for(path in listOf("/vehicles/client/installations/${VehicleProtocol.reference(c).charterText("id")}/cancel","/vehicles/client/installations/${VehicleProtocol.reference(c).charterText("id")}/replace","/me"))assertThrows(Exception::class.java){VehicleProtocol.validateRequest("POST",path,emptyMap(),buildJsonObject{})};assertThrows(Exception::class.java){VehicleProtocol.validateRequest("POST","/vehicles/client/installations",emptyMap(),JsonObject(VehicleProtocol.request(c)+("wallet" to JsonPrimitive("attacker"))))};assertThrows(Exception::class.java){VehicleProtocol.validateRequest("GET","/vehicles/client/activity",mapOf("cursor" to "bad/next"),null)}}
 @Test fun `missing catalogue never fabricates numeric policy and unsupported tiers fail`() {assertNull(VehiclePolicy.catalogue(null));assertThrows(Exception::class.java){policy.verifyClient(change(c,"record.reservation.identity.tier",JsonPrimitive(255)))};val client=f.charterObject("constants").charterObject("client");assertThrows(Exception::class.java){VehiclePolicy.from(JsonObject(f.charterObject("constants")+("client" to JsonObject(client+("rpcTimeoutMs" to JsonPrimitive("10000"))))))}}
}
